    internal class MotBaiTho
    {
        public string BaiTho = "\r\n\r\nWikipediaBách khoa toàn thư mở\r\nTìm kiếm trên Wikipedia\r\nTìm kiếm\r\nQuyên góp\r\nTạo tài khoản\r\nĐăng nhập\r\nBiểu quyết nội dung chọn lọc Bài viết chọn lọc: Summer of '69 • Rút sao: Lưu Bị • Sông Columbia\r\nBiểu quyết nội dung tốt Bài viết tốt: Huy Đức • Tseax Cone • Liyue (Genshin Impact) (lần 2) • Hội chứng nhược cơ Lambert–Eaton • Shin Seiki Evangelion (lần 2) • Bombus impatiens • Wake Me Up When September Ends (lần 2)\r\nĐóng (mở lại bằng cách xóa cookie dismissASN1 trong trình duyệt)\r\nNội dung ẩn\r\nĐầu\r\nNội dung\r\nẢnh hưởng\r\nTham khảo\r\nTôi thấy hoa vàng trên cỏ xanh\r\n\r\nBài viết\r\nThảo luận\r\nĐọc\r\nSửa đổi\r\nSửa mã nguồn\r\nXem lịch sử\r\n\r\nCông cụ\r\nGiao diện ẩn\r\nChế độ sinh nhật (Baby Globe)\r\n\r\nTắt\r\n\r\nBật\r\nTìm hiểu thêm về Chế độ sinh nhật\r\nVăn bản\r\n\r\nNhỏ\r\n\r\nTiêu chuẩn\r\n\r\nLớn\r\nChiều rộng\r\n\r\nTiêu chuẩn\r\n\r\nRộng\r\nMàu (thử nghiệm)\r\n\r\nTự động\r\n\r\nSáng\r\n\r\nTối\r\n\r\nXin hãy phát triển bài viết này. Nếu bài viết đã được phát triển, hãy gỡ bản mẫu này. Thông tin thêm có thể được tìm thấy tại trang thảo luận.\r\nBài này viết về một tiểu thuyết phát hành năm 2010. Đối với bộ phim được chuyển thể cùng tên, xem Tôi thấy hoa vàng trên cỏ xanh (phim).\r\nTôi thấy hoa vàng trên cỏ xanh\r\n\r\nẤn bản năm 2019 của Nhà xuất bản Trẻ.\r\nThông tin sách\r\nTác giả\tNguyễn Nhật Ánh\r\nMinh họa\tĐỗ Hoàng Tường\r\nQuốc gia\t Việt Nam\r\nNgôn ngữ\tTiếng Việt\r\nThể loại\tTiểu thuyết thanh thiếu niên\r\nNhà xuất bản\tNhà xuất bản Trẻ\r\nNgày phát hành\t9 tháng 12 năm 2010\r\nKiểu sách\tSách in\r\nSố trang\t378\r\nISBN\t978-604-1-00069-8\r\nOCLC\t755692277\r\nTôi thấy hoa vàng trên cỏ xanh là một tiểu thuyết dành cho thanh thiếu niên của nhà văn Nguyễn Nhật Ánh, xuất bản lần đầu tại Việt Nam vào ngày 9 tháng 12 năm 2010 bởi Nhà xuất bản Trẻ với phần tranh minh họa do Đỗ Hoàng Tường thực hiện. Đây là một trong các truyện dài của Nguyễn Nhật Ánh, ra đời sau Đảo mộng mơ và trước Lá nằm trong lá. Tác phẩm như một tập nhật ký xoay quanh cuộc sống của những đứa trẻ ở một vùng quê Việt Nam nghèo khó, nổi bật lên là thông điệp về tình anh em, tình làng nghĩa xóm và những tâm tư của tuổi mới lớn. Theo Nguyễn Nhật Ánh, đây là lần đầu tiên ông đưa vào truyện của mình những nhân vật phản diện, đặt ra vấn đề đạo đức như sự vô tâm hay cái ác\r\n\r\nLà một trong những quyển sách Việt Nam bán chạy nhất năm 2010, Tôi thấy hoa vàng trên cỏ xanh đã được tái bản ngay trong ngày phát hành đầu tiên, với tổng số bản in lên đến hơn 20.000 bản. Đây cũng là cuốn sách mở đầu cho phương thức in nhiều dạng ấn bản trên một tác phẩm ở Việt Nam, với ấn bản bìa mềm và bìa cứng được bán ra song song. Tôi thấy hoa vàng trên cỏ xanh được chuyển thể thành một bộ phim điện ảnh cùng tên bởi đạo diễn Victor Vũ, công chiếu vào tháng 10 năm 2015 với doanh thu phòng vé rất cao và gây được nhiều sự chú ý trong công chúng. Như một ảnh hưởng từ sức ảnh hưởng tích cực của bộ phim, tiểu thuyết đã trở thành quyển sách bán chạy nhất trong Hội sách Hà Nội năm 2015. Tính đến tháng 3 năm 2020, Tôi thấy hoa vàng trên cỏ xanh đã trải qua 43 lần tái phát hành với tổng số bản in lên đến hơn 300.000 bản.\r\n\r\nNội dung\r\nCâu chuyện là những trang nhật ký về cuộc sống thường ngày và tâm tư của cậu bé Thiều. Thiều đang là học sinh lớp 7 sống ở một vùng quê nghèo, cùng với người em trai tên Tường. Tường là một cậu bé dễ thương, hiền lành, bao dung, rất yêu mến anh trai và thích chơi đùa với nhiều loài động vật gồm cả sâu bọ, rắn rết. Cậu bé sống nội tâm, ham đọc sách và rất say mê những câu chuyện cổ tích, đặc biệt là truyện Cóc tía, chính vì vậy mà cậu nuôi nấng một con cóc dưới gầm giường và đặt tên cho nó là \"Cu Cậu\". Trong khi đó Thiều vốn là một người hướng ngoại, khá tinh quái, đã nhiều lần vô tình để em mình chịu tai bay vạ gió sau những trò nghịch phá do chính mình bày ra. Thiều cũng rất nhiều lần tỏ ra hẹp hòi, nhưng trong thâm tâm cậu vẫn rất thương em mình và là một người hào hiệp. Hai anh em Thiều và Tường thả hồn vào những trò chơi cảm giác mạnh và nhiều kỷ niệm đáng nhớ thời thơ ấu của những đứa trẻ làng quê. Truyện cũng mở rộng ra mối quan hệ giữa hai anh em và những người dân trong ngôi làng, gồm cả người thân của mình và những bạn học cùng lớp. Ba của Thiều được miêu tả là một người giảo hoạt và được dân làng yêu mến nhưng hay nổi nóng và thường xuyên đánh đòn hai anh em vì nhiều lý do, trong khi mẹ cậu tỏ ra dịu dàng với các con hơn dù bà cũng không tránh khỏi việc trách mắng khi các con làm điều sai quấy.\r\n\r\nChú Đàn là em trai của ba Thiều, bị mất một tay do tai nạn nhưng vẫn luôn yêu đời và thường kể chuyện ma cho hai anh em Thiều và Tường nghe. Tuy bị cụt mất một tay nhưng chú Đàn lại chơi đàn ắc - mô - ni - ca rất hay. Nỗi muộn phiền duy nhất của chú có lẽ nằm ở chuyện tình nhiều trắc trở do cánh tay cụt gây ra. Chú Đàn yêu chị Vinh, một cô gái cùng xóm và là con của thầy Nhãn, thầy giáo chủ nhiệm lớp của Thiều, người thầy mà lúc nào cũng làm cho Thiều sợ chết khiếp. Vào lúc mở đầu câu chuyện, Thiều cảm thấy thích một cô bạn cùng lớp ngồi kế bên cậu tên là Xin. Xin hay bị Thiều trêu chọc và từng có lần vô tình làm cho Thiều bẽ mặt trước lớp. Một bạn học khác của Thiều là Sơn, lớn hơn cậu ba tuổi nhưng học lực rất yếu và phải ở lại lớp liên tục 3 năm liền. Sơn được miêu tả là một đứa du côn, suốt ngày phá làng phá xóm và có những cử chỉ và lời nói khiếm nhã, thô tục. Về sau, Thiều nhận ra mình đã có tình cảm với Mận, là một cô bạn cùng lớp lớn hơn cậu một tuổi. Mận xinh xắn và ngây thơ nhưng học không được tốt do phải chăm sóc người cha mắc căn bệnh phong, đang bị mẹ cô bé giam trên gác nhà. Bí mật này chỉ có Thiều và Tường biết, và hai anh em đã phải ẩu đả với Sơn chỉ để bảo vệ Mận trước những âm mưu đen tối.\r\n\r\nBiến cố xảy ra khi căn gác nhà Mận bốc cháy, khiến ba Mận bị phỏng, được mọi người đồn đoán là đã chết cháy sau khi người ta phát hiện ra có xương lẫn trong đám tro. Chịu liền tiếp nhiều cú sốc lớn, Mận suy sụp hoàn toàn. Gia đình Thiều đã giúp đỡ Mận trong lúc khó khăn nhất và đưa cô bé về ở chung với mình. Mận biết được ba mình còn sống và mẹ sẽ được thả trong một ngày không xa. Tuy nhiên, sự thân thiết giữa Tường và Mận lại khiến cho cơn ghen tức trong lòng Thiều tăng lên theo thời gian. Cậu đã không can ngăn khi con cóc Tường nuôi bị bắt đi làm thịt, điều mà khiến Thiều ray rứt mãi bởi chứng kiến nỗi buồn đau của Tường dù cậu bé không hề biết là do anh mình tiếp tay. Mùa lũ đến, cả làng Thiều chìm trong nước, khi nước rút đi và để lại nhiều hậu quả tiêu cực như đói kém, mất mùa, Thiều, Tường và Mận mới phát hiện ra chị Vinh và chú Đàn đã lập ra kế hoạch cùng nhau bỏ trốn để thoát khỏi sự ngăn cấm của gia đình. Cùng lúc đó, sự hẹp hòi và đố kỵ trong lòng Thiều đã nhiều đến mức trong một phút hiểu lầm cậu đã vô tình khiến em trai mình bị thương nặng, không thể ngồi dậy được. Thiều càng ân hận hơn khi nghe chính miệng Tường kể rằng người mà Mận thích chơi cùng chính là cậu.\r\n\r\nMận được mẹ đón đi tìm cha, trong khi Thiều ở lại chìm trong nuối tiếc và cắn rứt mà tận tình chăm sóc cho Tường. Cả hai anh em đã giấu ba mẹ nguyên nhân thật sự gây ra cảnh ngộ rủi ro của Tường. Một hôm Thiều mừng rỡ khi thấy Tường đã ngồi dậy được và nghe em trai mình kể về một nàng công chúa không biết từ đâu đến mà đã trở thành nguồn động viên tinh thần để Tường hồi phục. Quá hiếu kỳ, trong một lần tình cờ phát hiện ra công chúa và lén lút bám theo, Thiều vô cùng bất ngờ khi biết nàng công chúa ấy thực ra là Nhi, con một người mổ lợn trong làng. Người làng lầm tưởng Nhi đã chết sau một vụ tai nạn ba năm trước, nhưng hóa ra cô bé vẫn sống nhưng có vấn đề về thần kinh, khiến cô tự xem mình là công chúa và cha mình là đức vua, người mà cũng vì thương con nên đã giả vờ diễn trò cùng cô bé. Thiều kể lại bí mật này với Tường lúc này đã đứng dậy được, bởi vì Tường và Nhi từng chơi rất thân với nhau. Sự nôn nóng được gặp lại Nhi thôi thúc Tường ra sức tập đi lại. Một ngày nọ hai anh em nhìn thấy Nhi đang bị đám trẻ con trong làng trêu chọc, Tường đã chạy hết sức bằng chính đôi chân mình đến bảo vệ Nhi, kỳ diệu thay nghĩa cử này khiến cô bé nhớ ra mọi chuyện và trở lại bình thường.\r\n\r\nẢnh hưởng\r\nTác phẩm Tôi thấy hoa vàng trên cỏ xanh của ông được ra mắt tại Nhật Bản bởi Canatia Communications,[1][2] trước đó tác phẩm Mắt biếc của ông cũng được xuất bản tại Nhật Bản bởi Terrain Inc. vào năm 2004.[2]\r\n\r\nTham khảo\r\n^ Lam Điền (ngày 13 tháng 12 năm 2017). \"'Tôi thấy hoa vàng trên cỏ xanh' có bản tiếng Nhật\". Tuổi Trẻ. Truy cập ngày 7 tháng 2 năm 2022.\r\n^ a b Lê Công Sơn (ngày 13 tháng 12 năm 2017). \"'Tôi thấy hoa vàng trên cỏ xanh' của Nguyễn Nhật Ánh ra mắt tại Nhật Bản\". Thanh Niên. Truy cập ngày 7 tháng 2 năm 2022.\r\nxts\r\nNguyễn Nhật Ánh\r\nBộ truyện\t\r\nKính vạn hoa (1995–2010)Chuyện xứ Lang Biang (2004–2006)\r\nTiểu thuyết\t\r\nTrước vòng chung kết (1985)Bàn có năm chỗ ngồi (1987)Còn chút gì để nhớ (1988)Cô gái đến từ hôm qua / Chú bé rắc rối / Nữ sinh (1989)Thiên thần nhỏ của tôi / Phòng trọ ba người / Mắt biếc / Thằng quỷ nhỏ (1990)Hoa hồng xứ khác / Hạ đỏ / Bong bóng lên trời (1991)Bồ câu không đưa thư / Những chàng trai xấu tính (1993)Trại hoa vàng (1994)Đi qua hoa cúc / Buổi chiều Windows / Quán Gò đi lên / Những cô em gái (2000)Tôi là Bêtô (2007)Ngôi trường mọi khi / Cho tôi xin một vé đi tuổi thơ (2008)Đảo mộng mơ (2009)Tôi thấy hoa vàng trên cỏ xanh (2010)Lá nằm trong lá (2011)Có hai con mèo ngồi bên cửa sổ (2012)Ngồi khóc trên cây (2013)Chúc một ngày tốt lành (2014)Bảy bước tới mùa hè (2015)Con chó nhỏ mang giỏ hoa hồng / Ngày xưa có một chuyện tình (2016)Cây chuối non đi giày xanh (2017)Cảm ơn người lớn (2018)Làm bạn với bầu trời (2019)Con chim xanh biếc bay về (2020)Ra bờ suối ngắm hoa kèn hồng (2022)Những người hàng xóm (2022)Mùa hè không tên (2023)Tiệm sách của nàng (2024)Cô bé hàng xóm và bốn viên kẹo (2025)\r\nTruyện ngắn\t\r\nCú phạt đền (1985)Chuyện cổ tích dành cho người lớn (1988)Bí mật của một võ sĩ (1989)Út Quyên và